export const PHANTOM_STATUS = {"html": "<h1 id=\"phantom-protocol-status\">Phantom Protocol — Status</h1>\n<p>What the Phantom Protocol does today, and what it does not yet do. Each row names the test that proves it. For unfinished work, it names the test that is switched off until the work lands — that test passes, unchanged, the day it is done.</p>\n<p><strong>Phantom is not yet used by any live TNHC service.</strong> Sign-in, email and the dashboard currently use ordinary HTTPS.</p>\n<table>\n<thead>\n<tr>\n<th>Capability</th>\n<th>Status</th>\n<th>Proved by</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Post-quantum signatures (Dilithium-5)</td>\n<td>Done</td>\n<td><code>test_dilithium_signatures</code> (phantom-crypto)</td>\n</tr>\n<tr>\n<td>Fully homomorphic encryption primitive</td>\n<td>Done</td>\n<td><code>test_fhe_basic_encryption</code> (phantom-crypto)</td>\n</tr>\n<tr>\n<td>Encrypted routing — a relay cannot learn the route</td>\n<td>Done</td>\n<td><code>test_routing_blob_construction</code> (phantom-routing)</td>\n</tr>\n<tr>\n<td>Multi-hop forwarding</td>\n<td>Partial — the test passes (about 47 seconds), but it is switched off in the default test run because the homomorphic encryption makes it slow, so routine checks do not exercise it</td>\n<td><code>test_multi_hop_forwarding</code> (phantom-routing)</td>\n</tr>\n<tr>\n<td>Replay protection</td>\n<td>Partial — repeated packet ids are rejected, but the nullifier is derived from the packet id, so a resent packet with a new id is not caught; the test passes but is switched off in the default test run (slow)</td>\n<td><code>test_replay_attack_detection</code> (phantom-routing)</td>\n</tr>\n<tr>\n<td>Message contents encrypted on the wire</td>\n<td>Not done</td>\n<td><code>payload_is_not_readable_on_the_wire</code> (phantom-routing)</td>\n</tr>\n<tr>\n<td>Membership proof (zero-knowledge)</td>\n<td>Not done — the circuit is incomplete, and the current proof generator is a hash, not zero-knowledge</td>\n<td><code>test_end_to_end_phantom_routing</code> (phantom-routing)</td>\n</tr>\n</tbody>\n</table>\n<p>This page is published at https://tnhc.dev/phantom. Licensed MIT OR Apache-2.0, like the code.</p>", "source": "https://github.com/The-No-Hands-company/Phantom/blob/main/STATUS.md", "commit": "980a0cdbeee2e45dd0bf4f94180662d6844c4a0f"};
